#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll com(ll a, ll b) {
    if (a == b || b == 0) return 1;
    if (b == 1) return a;
    return com(a - 1, b) + com(a - 1, b - 1);
}

int main() {
    ll n;
    cin >> n;

    ll m = 2 * n - 2;
    ll baki = m - n;
    ll maki = baki + 1;
    ll p = com(baki * 3, baki) * maki * 4;

    cout << p << '\n';
    return 0;
}

